  --color-border:     #e5e7eb;
  --color-muted:      #6b7280;
  --color-tag-bg:     #fff7ed;
  --color-tag-text:   #c2410c;
  --radius-sm:        6px;
  --radius-md:        12px;
  --radius-lg:        20px;
  --shadow-sm:        0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:        0 4px 16px rgba(0,0,0,.10);
  --shadow-lg:        0 10px 40px rgba(0,0,0,.12);
  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;
  --transition:       all .2s ease;
  --max-width:        1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-primary);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; width: 100%; height: auto; }

a { text-decoration: none; color: inherit; }

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

/* ============================================================
   LAYOUT HELPERS
   ============================================================ */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section { padding: 72px 0; }
.section-sm { padding: 48px 0; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 36px;
  gap: 16px;
}

.section-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -.4px;
  line-height: 1.2;
}

.section-title span { color: var(--color-accent); }

.section-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: var(--transition);
}

.section-link:hover { color: var(--color-accent-dk); gap: 8px; }

/* ============================================================
   ANNOUNCEMENT BAR
   ============================================================ */
.announcement-bar {
  background: var(--color-primary);
  color: #fff;
  text-align: center;
  font-size: 13px;
  font-weight: 500;
  padding: 10px 24px;
  letter-spacing: .02em;
}

.announcement-bar a { color: var(--color-accent); font-weight: 700; margin-left: 6px; }
.announcement-bar a:hover { text-decoration: underline; }

/* ============================================================
   HEADER / NAV
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 64px;
}

.logo {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -1px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.logo-dot { color: var(--color-accent); }

.main-nav {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-left: 16px;
}

.nav-link {
  font-size: 14px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  color: var(--color-muted);
  transition: var(--transition);
}

.nav-link:hover, .nav-link.active {
  color: var(--color-primary);
  background: var(--color-bg);
}

.nav-link.active { font-weight: 600; }

.header-search {
  flex: 1;
  max-width: 360px;
  margin-left: auto;
  position: relative;
}

.header-search input {
  width: 100%;
  height: 38px;
  padding: 0 14px 0 40px;
  border: 1.5px solid var(--color-border);
  border-radius: 999px;
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: var(--transition);
  background: var(--color-bg);
  color: var(--color-primary);
}

.header-search input:focus { border-color: var(--color-accent); background: #fff; }
.header-search input::placeholder { color: var(--color-muted); }

.search-icon {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-muted);
  pointer-events: none;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.icon-btn {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
  transition: var(--transition);
  position: relative;
}

.icon-btn:hover { background: var(--color-bg); color: var(--color-primary); }

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--color-accent);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-primary);
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
  border: none;
}

.btn-primary:hover { background: #1f2937; }

.btn-accent {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-accent);
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.btn-accent:hover { background: var(--color-accent-dk); }

.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  border: 2px solid rgba(255,255,255,.5);
  transition: var(--transition);
}

.btn-outline:hover { border-color: #fff; background: rgba(255,255,255,.1); }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  background: var(--color-primary);
  color: #fff;
  overflow: hidden;
  position: relative;
  min-height: 520px;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 520px;
}

.hero-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 80px 48px 80px 0;
  position: relative;
  z-index: 2;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 20px;
}

.hero-eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .4; }
}

.hero-title {
  font-size: clamp(36px, 5vw, 58px);
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.07;
  margin-bottom: 20px;
}

.hero-title em {
  font-style: normal;
  color: var(--color-accent);
}

.hero-desc {
  font-size: 16px;
  color: rgba(255,255,255,.65);
  max-width: 420px;
  margin-bottom: 36px;
  line-height: 1.7;
}

.hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 48px;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,.1);
}

.hero-stat-value {
  font-size: 22px;
  font-weight: 700;
  color: #fff;
}

.hero-stat-label {
  font-size: 12px;
  color: rgba(255,255,255,.5);
  margin-top: 2px;
}

.hero-visual {
  position: relative;
  overflow: hidden;
}

.hero-image-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1f2937 0%, #374151 50%, #1a1a2e 100%);
}

.hero-image-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(249,115,22,.15) 0%, transparent 65%);
}

.hero-product-card {
  position: absolute;
  background: rgba(255,255,255,.06);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: #fff;
}

.hero-product-card.card-1 { bottom: 80px; left: 32px; width: 200px; }
.hero-product-card.card-2 { top: 80px; right: 32px; width: 180px; }

.hero-product-emoji { font-size: 32px; }

.hero-product-name { font-size: 13px; font-weight: 600; }
.hero-product-price { font-size: 11px; color: rgba(255,255,255,.6); margin-top: 2px; }

.hero-badge {
  position: absolute;
  top: 36px;
  left: 32px;
  background: var(--color-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 999px;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.hero-circles {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero-circle {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.05);
}

.hero-circle-1 { width: 480px; height: 480px; top: -100px; right: -120px; }
.hero-circle-2 { width: 320px; height: 320px; bottom: -60px; left: 60px; }

/* ============================================================
   CATEGORY STRIP
   ============================================================ */
.category-strip { background: #fff; border-bottom: 1px solid var(--color-border); }

.categories-scroll {
  display: flex;
  gap: 8px;
  padding: 16px 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.categories-scroll::-webkit-scrollbar { display: none; }

.category-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  border-radius: 999px;
  border: 1.5px solid var(--color-border);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: var(--transition);
  background: #fff;
  flex-shrink: 0;
}

.category-chip:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: #fff;
}

.category-chip.active {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: #fff;
}

.category-chip-icon { font-size: 16px; }

/* ============================================================
   PRODUCT GRID
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  transition: var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
  border-color: transparent;
}

.product-image-wrap {
  position: relative;
  background: var(--color-bg);
  aspect-ratio: 1;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-emoji {
  font-size: 72px;
  user-select: none;
  transition: transform .3s ease;
}

.product-card:hover .product-emoji { transform: scale(1.1); }

.product-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.tag-new { background: #dbeafe; color: #1d4ed8; }
.tag-sale { background: #fee2e2; color: #dc2626; }
.tag-hot { background: #fef3c7; color: #d97706; }
.tag-limited { background: #f3e8ff; color: #7c3aed; }

.product-wishlist {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(255,255,255,.9);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  cursor: pointer;
  transition: var(--transition);
  border: none;
  opacity: 0;
}

.product-card:hover .product-wishlist { opacity: 1; }
.product-wishlist:hover { background: #fff; box-shadow: var(--shadow-sm); }
.product-wishlist.active { opacity: 1; }

.product-info {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-brand {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-muted);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 4px;
}

.product-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 8px;
  line-height: 1.4;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  margin-bottom: 12px;
}

.stars { color: #f59e0b; letter-spacing: 1px; }
.rating-count { color: var(--color-muted); }

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
}

.product-price { font-size: 18px; font-weight: 700; }

.product-price-old {
  font-size: 13px;
  color: var(--color-muted);
  text-decoration: line-through;
  margin-left: 6px;
  font-weight: 400;
}

.product-add-btn {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  background: var(--color-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 400;
  line-height: 1;
  transition: var(--transition);
  flex-shrink: 0;
}

.product-add-btn:hover { background: var(--color-accent); }

/* ============================================================
   DEALS SECTION
   ============================================================ */
.deals-section { background: #fff; }

.deals-banner {
  background: linear-gradient(135deg, var(--color-primary) 0%, #1e3a5f 100%);
  border-radius: var(--radius-lg);
  padding: 48px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 32px;
  align-items: center;
  margin-bottom: 40px;
  overflow: hidden;
  position: relative;
}

.deals-banner::before {
  content: '';
  position: absolute;
  right: -60px;
  top: -60px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: rgba(249,115,22,.12);
}

.deals-banner::after {
  content: '';
  position: absolute;
  right: 120px;
  bottom: -80px;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: rgba(249,115,22,.08);
}

.deals-banner-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 12px;
}

.deals-banner-title {
  font-size: 32px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -.5px;
  margin-bottom: 8px;
  line-height: 1.2;
}

.deals-banner-sub {
  color: rgba(255,255,255,.6);
  font-size: 15px;
}

.countdown {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.countdown-unit {
  text-align: center;
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  min-width: 68px;
}

.countdown-value {
  font-size: 28px;
  font-weight: 800;
  color: #fff;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.countdown-label {
  font-size: 11px;
  color: rgba(255,255,255,.5);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-top: 4px;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.deal-card {
  background: var(--color-bg);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  gap: 20px;
  align-items: center;
  border: 1px solid var(--color-border);
  transition: var(--transition);
  cursor: pointer;
}

.deal-card:hover {
  box-shadow: var(--shadow-md);
  border-color: transparent;
  transform: translateY(-2px);
}

.deal-emoji {
  font-size: 52px;
  flex-shrink: 0;
}

.deal-info { flex: 1; min-width: 0; }

.deal-tag {
  display: inline-block;
  background: var(--color-tag-bg);
  color: var(--color-tag-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: .05em;
  margin-bottom: 8px;
}

.deal-name { font-size: 15px; font-weight: 600; margin-bottom: 8px; line-height: 1.3; }

.deal-price-row { display: flex; align-items: baseline; gap: 8px; }
.deal-price { font-size: 20px; font-weight: 800; color: var(--color-primary); }
.deal-price-old { font-size: 13px; color: var(--color-muted); text-decoration: line-through; }
.deal-savings { font-size: 12px; font-weight: 700; color: #16a34a; }

.deal-progress-wrap { margin-top: 12px; }
.deal-progress-label { display: flex; justify-content: space-between; font-size: 11px; color: var(--color-muted); margin-bottom: 4px; }
.deal-progress-bar { height: 5px; background: var(--color-border); border-radius: 999px; overflow: hidden; }
.deal-progress-fill { height: 100%; background: linear-gradient(90deg, var(--color-accent), #f59e0b); border-radius: 999px; transition: width 1s ease; }

/* ============================================================
   EDITORIAL / COLLECTIONS BANNER
   ============================================================ */
.editorial-section { background: var(--color-bg); }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: 240px 240px;
  gap: 16px;
}

.editorial-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  display: flex;
  align-items: flex-end;
}

.editorial-card.featured { grid-row: 1 / 3; }

.editorial-bg {
  position: absolute;
  inset: 0;
  transition: transform .4s ease;
}

.editorial-card:hover .editorial-bg { transform: scale(1.04); }

.editorial-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.75) 0%, rgba(0,0,0,.2) 50%, transparent 100%);
}

.editorial-content {
  position: relative;
  z-index: 2;
  padding: 24px;
  color: #fff;
  width: 100%;
}

.editorial-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(255,255,255,.7);
  margin-bottom: 6px;
}

.editorial-title {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 12px;
}

.editorial-card:not(.featured) .editorial-title { font-size: 16px; }

.editorial-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  background: rgba(255,255,255,.15);
  border: 1px solid rgba(255,255,255,.25);
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
  backdrop-filter: blur(4px);
}

.editorial-cta:hover { background: rgba(255,255,255,.25); }

/* Editorial color themes */
.theme-indigo .editorial-bg { background: linear-gradient(160deg, #1e3a8a 0%, #4338ca 100%); }
.theme-rose   .editorial-bg { background: linear-gradient(160deg, #881337 0%, #e11d48 100%); }
.theme-teal   .editorial-bg { background: linear-gradient(160deg, #134e4a 0%, #0d9488 100%); }
.theme-amber  .editorial-bg { background: linear-gradient(160deg, #92400e 0%, #f59e0b 100%); }

.editorial-deco {
  position: absolute;
  font-size: 100px;
  opacity: .12;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  user-select: none;
  pointer-events: none;
}

.editorial-card.featured .editorial-deco { font-size: 160px; right: 24px; }

/* ============================================================
   TRENDING / MARQUEE
   ============================================================ */
.trending-strip {
  background: var(--color-primary);
  color: #fff;
  padding: 14px 0;
  overflow: hidden;
  white-space: nowrap;
}

.trending-track {
  display: inline-flex;
  animation: marquee 28s linear infinite;
}

.trending-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 500;
  padding: 0 28px;
}

.trending-item-dot { color: var(--color-accent); font-size: 18px; line-height: 1; }

@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ============================================================
   REVIEWS STRIP
   ============================================================ */
.reviews-section { background: #fff; }

.reviews-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.review-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 24px;
}

.review-stars { font-size: 16px; color: #f59e0b; margin-bottom: 12px; }

.review-text {
  font-size: 14px;
  line-height: 1.7;
