+.product-card:hover .product-wishlist { opacity: 1; }
+.product-wishlist:hover { background: #fff; box-shadow: var(--shadow-sm); }
+.product-wishlist.active { opacity: 1; }
+
+.product-info {
+  padding: 16px;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+
+.product-brand {
+  font-size: 11px;
+  font-weight: 600;
+  color: var(--color-muted);
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  margin-bottom: 4px;
+}
+
+.product-name {
+  font-size: 14px;
+  font-weight: 600;
+  color: var(--color-primary);
+  margin-bottom: 8px;
+  line-height: 1.4;
+}
+
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 12px;
+  margin-bottom: 12px;
+}
+
+.stars { color: #f59e0b; letter-spacing: 1px; }
+.rating-count { color: var(--color-muted); }
+
+.product-footer {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  margin-top: auto;
+}
+
+.product-price { font-size: 18px; font-weight: 700; }
+
+.product-price-old {
+  font-size: 13px;
+  color: var(--color-muted);
+  text-decoration: line-through;
+  margin-left: 6px;
+  font-weight: 400;
+}
+
+.product-add-btn {
+  width: 34px;
+  height: 34px;
+  border-radius: var(--radius-sm);
+  background: var(--color-primary);
+  color: #fff;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 18px;
+  font-weight: 400;
+  line-height: 1;
+  transition: var(--transition);
+  flex-shrink: 0;
+}
+
+.product-add-btn:hover { background: var(--color-accent); }
+
+/* ============================================================
+   DEALS SECTION
+   ============================================================ */
+.deals-section { background: #fff; }
+
+.deals-banner {
+  background: linear-gradient(135deg, var(--color-primary) 0%, #1e3a5f 100%);
+  border-radius: var(--radius-lg);
+  padding: 48px;
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: 32px;
+  align-items: center;
+  margin-bottom: 40px;
+  overflow: hidden;
+  position: relative;
+}
+
+.deals-banner::before {
+  content: '';
+  position: absolute;
+  right: -60px;
+  top: -60px;
+  width: 300px;
+  height: 300px;
+  border-radius: 50%;
+  background: rgba(249,115,22,.12);
+}
+
+.deals-banner::after {
+  content: '';
+  position: absolute;
+  right: 120px;
+  bottom: -80px;
+  width: 200px;
+  height: 200px;
+  border-radius: 50%;
+  background: rgba(249,115,22,.08);
+}
+
+.deals-banner-label {
+  font-size: 12px;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: 12px;
+}
+
+.deals-banner-title {
+  font-size: 32px;
+  font-weight: 800;
+  color: #fff;
+  letter-spacing: -.5px;
+  margin-bottom: 8px;
+  line-height: 1.2;
+}
+
+.deals-banner-sub {
+  color: rgba(255,255,255,.6);
+  font-size: 15px;
+}
+
+.countdown {
+  display: flex;
+  gap: 12px;
+  flex-shrink: 0;
+  position: relative;
+  z-index: 1;
+}
+
+.countdown-unit {
+  text-align: center;
+  background: rgba(255,255,255,.1);
+  border: 1px solid rgba(255,255,255,.15);
+  border-radius: var(--radius-sm);
+  padding: 12px 16px;
+  min-width: 68px;
+}
+
+.countdown-value {
+  font-size: 28px;
+  font-weight: 800;
+  color: #fff;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+
+.countdown-label {
+  font-size: 11px;
+  color: rgba(255,255,255,.5);
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  margin-top: 4px;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 20px;
+}
+
+.deal-card {
+  background: var(--color-bg);
+  border-radius: var(--radius-md);
+  padding: 24px;
+  display: flex;
+  gap: 20px;
+  align-items: center;
+  border: 1px solid var(--color-border);
+  transition: var(--transition);
+  cursor: pointer;
+}
+
+.deal-card:hover {
+  box-shadow: var(--shadow-md);
+  border-color: transparent;
+  transform: translateY(-2px);
+}
+
+.deal-emoji {
+  font-size: 52px;
+  flex-shrink: 0;
+}
+
+.deal-info { flex: 1; min-width: 0; }
+
+.deal-tag {
+  display: inline-block;
+  background: var(--color-tag-bg);
+  color: var(--color-tag-text);
+  font-size: 11px;
+  font-weight: 700;
+  padding: 3px 10px;
+  border-radius: 999px;
+  text-transform: uppercase;
+  letter-spacing: .05em;
+  margin-bottom: 8px;
+}
+
+.deal-name { font-size: 15px; font-weight: 600; margin-bottom: 8px; line-height: 1.3; }
+
+.deal-price-row { display: flex; align-items: baseline; gap: 8px; }
+.deal-price { font-size: 20px; font-weight: 800; color: var(--color-primary); }
+.deal-price-old { font-size: 13px; color: var(--color-muted); text-decoration: line-through; }
+.deal-savings { font-size: 12px; font-weight: 700; color: #16a34a; }
+
+.deal-progress-wrap { margin-top: 12px; }
+.deal-progress-label { display: flex; justify-content: space-between; font-size: 11px; color: var(--color-muted); margin-bottom: 4px; }
+.deal-progress-bar { height: 5px; background: var(--color-border); border-radius: 999px; overflow: hidden; }
+.deal-progress-fill { height: 100%; background: linear-gradient(90deg, var(--color-accent), #f59e0b); border-radius: 999px; transition: width 1s ease; }
+
+/* ============================================================
+   EDITORIAL / COLLECTIONS BANNER
+   ============================================================ */
+.editorial-section { background: var(--color-bg); }
+
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: 240px 240px;
+  gap: 16px;
+}
+
+.editorial-card {
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  position: relative;
+  cursor: pointer;
+  display: flex;
+  align-items: flex-end;
+}
+
+.editorial-card.featured { grid-row: 1 / 3; }
+
+.editorial-bg {
+  position: absolute;
+  inset: 0;
+  transition: transform .4s ease;
+}
+
+.editorial-card:hover .editorial-bg { transform: scale(1.04); }
+
+.editorial-overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,.75) 0%, rgba(0,0,0,.2) 50%, transparent 100%);
+}
+
+.editorial-content {
+  position: relative;
+  z-index: 2;
+  padding: 24px;
+  color: #fff;
+  width: 100%;
+}
+
+.editorial-label {
+  font-size: 11px;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: rgba(255,255,255,.7);
+  margin-bottom: 6px;
+}
+
+.editorial-title {
+  font-size: 20px;
+  font-weight: 700;
+  line-height: 1.3;
+  margin-bottom: 12px;
+}
+
+.editorial-card:not(.featured) .editorial-title { font-size: 16px; }
+
+.editorial-cta {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 13px;
+  font-weight: 600;
+  color: #fff;
+  background: rgba(255,255,255,.15);
+  border: 1px solid rgba(255,255,255,.25);
+  padding: 7px 14px;
+  border-radius: var(--radius-sm);
+  transition: var(--transition);
+  backdrop-filter: blur(4px);
+}
+
+.editorial-cta:hover { background: rgba(255,255,255,.25); }
+
+/* Editorial color themes */
+.theme-indigo .editorial-bg { background: linear-gradient(160deg, #1e3a8a 0%, #4338ca 100%); }
+.theme-rose   .editorial-bg { background: linear-gradient(160deg, #881337 0%, #e11d48 100%); }
+.theme-teal   .editorial-bg { background: linear-gradient(160deg, #134e4a 0%, #0d9488 100%); }
+.theme-amber  .editorial-bg { background: linear-gradient(160deg, #92400e 0%, #f59e0b 100%); }
+
+.editorial-deco {
+  position: absolute;
+  font-size: 100px;
+  opacity: .12;
+  right: 16px;
+  top: 50%;
+  transform: translateY(-50%);
+  user-select: none;
+  pointer-events: none;
+}
+
+.editorial-card.featured .editorial-deco { font-size: 160px; right: 24px; }
+
+/* ============================================================
+   TRENDING / MARQUEE
+   ============================================================ */
+.trending-strip {
+  background: var(--color-primary);
+  color: #fff;
+  padding: 14px 0;
+  overflow: hidden;
+  white-space: nowrap;
+}
+
+.trending-track {
+  display: inline-flex;
+  animation: marquee 28s linear infinite;
+}
+
+.trending-item {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  font-size: 13px;
+  font-weight: 500;
+  padding: 0 28px;
+}
+
+.trending-item-dot { color: var(--color-accent); font-size: 18px; line-height: 1; }
+
+@keyframes marquee {
+  from { transform: translateX(0); }
+  to   { transform: translateX(-50%); }
+}
+
+/* ============================================================
+   REVIEWS STRIP
+   ============================================================ */
+.reviews-section { background: #fff; }
+
+.reviews-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 20px;
+}
+
+.review-card {
+  background: var(--color-bg);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  padding: 24px;
+}
+
+.review-stars { font-size: 16px; color: #f59e0b; margin-bottom: 12px; }
+
+.review-text {
+  font-size: 14px;
+  line-height: 1.7;
+  color: #374151;
+  margin-bottom: 16px;
+  font-style: italic;
+}
+
+.review-author { display: flex; align-items: center; gap: 12px; }
+
+.review-avatar {
+  width: 38px;
+  height: 38px;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 18px;
+  flex-shrink: 0;
+}
+
+.review-name { font-size: 13px; font-weight: 600; }
+.review-date { font-size: 11px; color: var(--color-muted); margin-top: 1px; }
+
+/* ============================================================
+   NEWSLETTER
+   ============================================================ */
+.newsletter-section { background: var(--color-bg); }
+
+.newsletter-card {
+  background: var(--color-primary);
+  border-radius: var(--radius-lg);
+  padding: 64px 48px;
+  text-align: center;
+  position: relative;
+  overflow: hidden;
+}
+
+.newsletter-card::before {
+  content: '';
+  position: absolute;
+  left: -80px; top: -80px;
+  width: 280px; height: 280px;
+  border-radius: 50%;
+  background: rgba(249,115,22,.12);
+}
+
+.newsletter-card::after {
+  content: '';
+  position: absolute;
+  right: -60px; bottom: -60px;
+  width: 220px; height: 220px;
+  border-radius: 50%;
+  background: rgba(249,115,22,.08);
+}
+
+.newsletter-label {
+  font-size: 12px;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: 12px;
+}
+
+.newsletter-title {
+  font-size: 32px;
+  font-weight: 800;
+  color: #fff;
+  letter-spacing: -.5px;
+  margin-bottom: 12px;
+}
+
+.newsletter-sub {
+  color: rgba(255,255,255,.6);
+  font-size: 15px;
+  margin-bottom: 32px;
+}
+
+.newsletter-form {
+  display: flex;
+  gap: 10px;
+  max-width: 480px;
+  margin: 0 auto;
+  position: relative;
+  z-index: 1;
+}
+
+.newsletter-input {
+  flex: 1;
+  height: 48px;
+  padding: 0 18px;
+  border-radius: var(--radius-sm);
+  border: 1.5px solid rgba(255,255,255,.2);
+  background: rgba(255,255,255,.08);
+  color: #fff;
+  font-size: 14px;
+  font-family: inherit;
+  outline: none;
+  transition: var(--transition);
+}
+
+.newsletter-input::placeholder { color: rgba(255,255,255,.4); }
+.newsletter-input:focus { border-color: var(--color-accent); background: rgba(255,255,255,.12); }
+
+.newsletter-btn {
+  height: 48px;
+  padding: 0 24px;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: 14px;
+  font-weight: 700;
+  border-radius: var(--radius-sm);
+  border: none;
+  cursor: pointer;
+  white-space: nowrap;
+  transition: var(--transition);
+  flex-shrink: 0;
+}
+
+.newsletter-btn:hover { background: var(--color-accent-dk); }
+
+/* ============================================================
+   FOOTER
+   ============================================================ */
+.site-footer { background: var(--color-primary); color: rgba(255,255,255,.7); padding-top: 60px; }
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr 1fr;
+  gap: 48px;
+  padding-bottom: 48px;
+  border-bottom: 1px solid rgba(255,255,255,.1);
+}
+
+.footer-brand-name {
+  font-size: 22px;
+  font-weight: 800;
+  color: #fff;
+  letter-spacing: -1px;
+  margin-bottom: 12px;
+}
+
+.footer-tagline { font-size: 14px; line-height: 1.7; margin-bottom: 24px; }
+
+.footer-socials { display: flex; gap: 8px; }
+
+.footer-social {
+  width: 36px;
+  height: 36px;
+  border-radius: var(--radius-sm);
+  background: rgba(255,255,255,.08);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 16px;
+  transition: var(--transition);
+  cursor: pointer;
+}
+
+.footer-social:hover { background: var(--color-accent); }
+
+.footer-col-title {
+  font-size: 13px;
+  font-weight: 700;
+  color: #fff;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  margin-bottom: 20px;
+}
+
+.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
+
+.footer-links a {
+  font-size: 14px;
+  color: rgba(255,255,255,.6);
+  transition: var(--transition);
+}
+
+.footer-links a:hover { color: #fff; padding-left: 4px; }
+
+.footer-bottom {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 20px 0;
+  font-size: 13px;
+  flex-wrap: wrap;
+  gap: 12px;
+}
+
+.footer-bottom-links { display: flex; gap: 20px; }
+.footer-bottom-links a { color: rgba(255,255,255,.4); transition: var(--transition); }
+.footer-bottom-links a:hover { color: rgba(255,255,255,.8); }
+
+/* ============================================================
+   TOAST NOTIFICATION
+   ============================================================ */
+.toast {
+  position: fixed;
+  bottom: 24px;
+  right: 24px;
+  background: var(--color-primary);
+  color: #fff;
+  padding: 14px 20px;
+  border-radius: var(--radius-md);
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  font-size: 14px;
+  font-weight: 500;
+  box-shadow: var(--shadow-lg);
+  z-index: 999;
+  transform: translateY(20px);
+  opacity: 0;
+  transition: all .3s cubic-bezier(.34,1.56,.64,1);
+  pointer-events: none;
+  max-width: 300px;
+}
+
+.toast.show { transform: translateY(0); opacity: 1; }
+.toast-icon { font-size: 18px; }
+
+/* ============================================================
+   RESPONSIVE
+   ============================================================ */
+@media (max-width: 1024px) {
+  .products-grid { grid-template-columns: repeat(3, 1fr); }
+  .deals-grid { grid-template-columns: 1fr 1fr; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+}
+
+@media (max-width: 768px) {
+  .main-nav { display: none; }
+
+  .hero-grid { grid-template-columns: 1fr; }
+  .hero-visual { display: none; }
+  .hero-content { padding: 56px 0; }
+
+  .products-grid { grid-template-columns: repeat(2, 1fr); }
+
+  .deals-banner { grid-template-columns: 1fr; }
+  .deals-grid { grid-template-columns: 1fr; }
+
+  .editorial-grid {
+    grid-template-columns: 1fr 1fr;
+    grid-template-rows: auto;
+  }
+  .editorial-card.featured { grid-row: auto; grid-column: 1 / 3; }
+
+  .reviews-grid { grid-template-columns: 1fr; }
+
+  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
+
+  .newsletter-form { flex-direction: column; }
+}
+
+@media (max-width: 480px) {
+  .products-grid { grid-template-columns: 1fr; }
+  .footer-grid { grid-template-columns: 1fr; }
+  .hero-stats { gap: 20px; }
+}
+
")

